interface ToolCall {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  status: 'pending' | 'approved' | 'rejected' | 'running' | 'completed' | 'failed';
  result?: unknown;
  error?: string;
  requiresApproval: boolean;
}

function ToolCallCard({ toolCall, onApprove, onReject }: {
  toolCall: ToolCall;
  onApprove: (id: string) => void;
  onReject: (id: string) => void;
}) {
  return (
    <div className={`tool-call-card status-${toolCall.status}`}>
      <div className="tool-name">{toolCall.name}</div>
      <div className="tool-arguments">
        {JSON.stringify(toolCall.arguments, null, 2)}
      </div>

      {toolCall.requiresApproval && toolCall.status === 'pending' && (
        <div className="approval-actions">
          <button onClick={() => onApprove(toolCall.id)}>Approve</button>
          <button onClick={() => onReject(toolCall.id)}>Reject</button>
        </div>
      )}

      {toolCall.status === 'running' && (
        <div className="status-indicator">Running...</div>
      )}

      {toolCall.status === 'completed' && toolCall.result && (
        <div className="tool-result">
          {JSON.stringify(toolCall.result, null, 2)}
        </div>
      )}

      {toolCall.status === 'failed' && (
        <div className="error">{toolCall.error}</div>
      )}
    </div>
  );
}
